#!/usr/bin/env python3
"""Merge user data from three sources with differing schemas."""
import json
import os
import re
import csv
import datetime

import pandas as pd

SOURCE_A = "/data/source_a/users.json"
SOURCE_B = "/data/source_b/users.csv"
SOURCE_C = "/data/source_c/users.parquet"
OUT_PARQUET = "/app/merged_users.parquet"
OUT_CONFLICTS = "/app/conflicts.json"

PRIORITY = ["source_a", "source_b", "source_c"]

FIELD_MAP = {
    # user_id
    "user_id": "user_id", "id": "user_id", "userid": "user_id",
    "uid": "user_id",
    # email
    "email": "email", "email_address": "email", "emailaddress": "email",
    "mail": "email",
    # name
    "full_name": "name", "name": "name", "username": "name",
    "fullname": "name",
    # created date
    "registration_date": "created_date", "created_at": "created_date",
    "joined": "created_date", "created_date": "created_date",
    "joined_date": "created_date", "signup_date": "created_date",
    # status
    "status": "status", "is_active": "status", "active": "status",
    "state": "status",
}

OUT_FIELDS = ["name", "email", "created_date", "status"]


def canon_key(key):
    k = str(key).strip().lower().replace(" ", "_").replace("-", "_")
    if k in FIELD_MAP:
        return FIELD_MAP[k]
    k2 = k.replace("_", "")
    return FIELD_MAP.get(k2)


def norm_date(value):
    """Return YYYY-MM-DD string or None."""
    if value is None:
        return None
    if isinstance(value, float) and pd.isna(value):
        return None
    if isinstance(value, (datetime.datetime, datetime.date)):
        return value.strftime("%Y-%m-%d")
    if isinstance(value, pd.Timestamp):
        return value.strftime("%Y-%m-%d")
    s = str(value).strip()
    if not s or s.lower() in ("nan", "nat", "none", "null"):
        return None
    m = re.match(r"^(\d{4})-(\d{2})-(\d{2})", s)
    if m:
        return "%s-%s-%s" % m.groups()
    m = re.match(r"^(\d{4})/(\d{2})/(\d{2})", s)
    if m:
        return "%s-%s-%s" % m.groups()
    m = re.match(r"^(\d{2})/(\d{2})/(\d{4})$", s)
    if m:
        mm, dd, yyyy = m.groups()
        return "%s-%s-%s" % (yyyy, mm, dd)
    # numeric epoch
    try:
        num = float(s)
        if num > 1e11:
            num /= 1000.0
        return datetime.datetime.utcfromtimestamp(num).strftime("%Y-%m-%d")
    except (ValueError, OverflowError, OSError):
        pass
    try:
        return pd.to_datetime(s).strftime("%Y-%m-%d")
    except Exception:
        return s


def norm_status(value):
    if value is None:
        return None
    if isinstance(value, float) and pd.isna(value):
        return None
    if isinstance(value, bool):
        return "active" if value else "inactive"
    s = str(value).strip()
    if not s or s.lower() in ("nan", "none", "null"):
        return None
    low = s.lower()
    if low in ("true", "1", "yes", "y", "t"):
        return "active"
    if low in ("false", "0", "no", "n", "f"):
        return "inactive"
    return low


def norm_text(value):
    if value is None:
        return None
    if isinstance(value, float) and pd.isna(value):
        return None
    s = str(value).strip()
    if not s or s.lower() in ("nan", "none", "null"):
        return None
    return s


def norm_id(value):
    if value is None:
        return None
    try:
        if isinstance(value, str):
            value = value.strip()
            if not value:
                return None
        return int(float(value))
    except (ValueError, TypeError):
        return None


def normalize_record(raw):
    """Map arbitrary keys -> unified schema."""
    rec = {}
    for key, value in raw.items():
        field = canon_key(key)
        if field is None:
            continue
        if field == "user_id":
            value = norm_id(value)
        elif field == "created_date":
            value = norm_date(value)
        elif field == "status":
            value = norm_status(value)
        else:
            value = norm_text(value)
        if value is None:
            continue
        if field not in rec:
            rec[field] = value
    return rec


def load_json(path):
    if not os.path.exists(path):
        return []
    with open(path, "r", encoding="utf-8") as fh:
        text = fh.read().strip()
    if not text:
        return []
    try:
        data = json.loads(text)
    except json.JSONDecodeError:
        data = [json.loads(line) for line in text.splitlines() if line.strip()]
    if isinstance(data, dict):
        for key in ("users", "data", "records", "items"):
            if isinstance(data.get(key), list):
                data = data[key]
                break
        else:
            data = [data]
    return [normalize_record(r) for r in data if isinstance(r, dict)]


def load_csv(path):
    if not os.path.exists(path):
        return []
    with open(path, "r", encoding="utf-8-sig", newline="") as fh:
        reader = csv.DictReader(fh)
        return [normalize_record(row) for row in reader]


def load_parquet(path):
    if not os.path.exists(path):
        return []
    df = pd.read_parquet(path)
    records = df.to_dict(orient="records")
    return [normalize_record(r) for r in records]


def main():
    sources = {
        "source_a": load_json(SOURCE_A),
        "source_b": load_csv(SOURCE_B),
        "source_c": load_parquet(SOURCE_C),
    }

    # user_id -> source -> record
    per_user = {}
    order = []
    for src in PRIORITY:
        for rec in sources[src]:
            uid = rec.get("user_id")
            if uid is None:
                continue
            if uid not in per_user:
                per_user[uid] = {}
                order.append(uid)
            if src not in per_user[uid]:
                per_user[uid][src] = rec
            else:
                for k, v in rec.items():
                    per_user[uid][src].setdefault(k, v)

    merged_rows = []
    conflicts = []
    for uid in sorted(order):
        by_src = per_user[uid]
        row = {"user_id": int(uid)}
        for field in OUT_FIELDS:
            values = {}
            for src in PRIORITY:
                rec = by_src.get(src)
                if rec is not None and field in rec:
                    values[src] = rec[field]
            if not values:
                row[field] = None
                continue
            selected = values[[s for s in PRIORITY if s in values][0]]
            row[field] = selected
            if len(set(values.values())) > 1:
                conflicts.append({
                    "user_id": int(uid),
                    "field": field,
                    "values": {s: values[s] for s in PRIORITY if s in values},
                    "selected": selected,
                })
        merged_rows.append(row)

    df = pd.DataFrame(merged_rows, columns=["user_id", "name", "email",
                                            "created_date", "status"])
    df["user_id"] = df["user_id"].astype("int64")
    for col in ("name", "email", "created_date", "status"):
        df[col] = df[col].astype("object")
    os.makedirs(os.path.dirname(OUT_PARQUET), exist_ok=True)
    df.to_parquet(OUT_PARQUET, index=False)

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open(OUT_CONFLICTS, "w", encoding="utf-8") as fh:
        json.dump(report, fh, indent=2)

    print(df.to_string(index=False))
    print("conflicts:", len(conflicts))


if __name__ == "__main__":
    main()
